package com.cloudmall.stock;
import com.cloudmall.common.api.ApiResponse;import com.cloudmall.common.error.*;import org.springframework.web.bind.annotation.*;import java.util.*;import java.util.concurrent.*;
@RestController @RequestMapping("/api/stock") public class StockController{static final Map<Long,Integer> AVAILABLE=new ConcurrentHashMap<>();static final Map<String,Integer> RESERVED=new ConcurrentHashMap<>();static final Set<String> FLOWS=ConcurrentHashMap.newKeySet();static{AVAILABLE.put(1L,100);}
 @GetMapping("/skus/{skuId}")public ApiResponse<?> get(@PathVariable Long skuId){return ApiResponse.ok(Map.of("skuId",skuId,"availableQuantity",AVAILABLE.getOrDefault(skuId,0)));}
 @PostMapping("/reservations")public synchronized ApiResponse<?> reserve(@RequestBody Reservation r){if(!FLOWS.add("R:"+r.orderNo))return ApiResponse.ok(Map.of("reserved",true,"idempotent",true));for(Line l:r.items){if(l.quantity<1||AVAILABLE.getOrDefault(l.skuId,0)<l.quantity){FLOWS.remove("R:"+r.orderNo);throw new BizException(ErrorCodes.STOCK,"库存不足",409);}}for(Line l:r.items){AVAILABLE.compute(l.skuId,(k,v)->v-l.quantity);RESERVED.merge(r.orderNo,l.quantity,Integer::sum);}return ApiResponse.ok(Map.of("reserved",true));}
 @PostMapping("/reservations/{orderNo}/confirm")public synchronized ApiResponse<?> confirm(@PathVariable String orderNo){if(!FLOWS.add("C:"+orderNo))return ApiResponse.ok(null);RESERVED.remove(orderNo);return ApiResponse.ok(null);}@PostMapping("/reservations/{orderNo}/rollback")public synchronized ApiResponse<?> rollback(@PathVariable String orderNo){if(!FLOWS.add("B:"+orderNo))return ApiResponse.ok(null);int n=RESERVED.getOrDefault(orderNo,0);AVAILABLE.merge(1L,n,Integer::sum);RESERVED.remove(orderNo);return ApiResponse.ok(null);}
 @PostMapping("/seckill/reservations")public synchronized ApiResponse<?> seckill(@RequestBody Map<String,Object>b){String key="S:"+b.get("activityId")+":"+b.get("userId");if(!FLOWS.add(key))throw new BizException("ORDER_DUPLICATE_REQUEST","请勿重复抢购",409);Long sku=Long.valueOf(String.valueOf(b.get("skuId")));int n=AVAILABLE.getOrDefault(sku,0);if(n<1){FLOWS.remove(key);throw new BizException("SECKILL_SOLD_OUT","秒杀库存耗尽",409);}AVAILABLE.put(sku,n-1);return ApiResponse.ok(Map.of("accepted",true));}
 public static class Reservation{public String orderNo;public List<Line>items=new ArrayList<>();}public static class Line{public Long skuId;public int quantity;}}
